-- Additive only: existing responses and published revision bytes are unchanged.
CREATE TABLE confirmation_deliveries (
 id TEXT PRIMARY KEY,
 response_id TEXT NOT NULL UNIQUE REFERENCES responses(id) ON DELETE CASCADE,
 recipient TEXT,
 message_json TEXT CHECK(message_json IS NULL OR json_valid(message_json)),
 status TEXT NOT NULL CHECK(status IN ('pending','sending','sent','failed','unknown','cancelled')),
 attempts INTEGER NOT NULL DEFAULT 0,
 first_attempt_at TEXT, last_attempt_at TEXT, available_at TEXT NOT NULL,
 provider_id TEXT, reason TEXT,
 armed INTEGER NOT NULL DEFAULT 0 CHECK(armed IN (0,1)),
 created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE INDEX confirmation_deliveries_due ON confirmation_deliveries(status,armed,available_at);
CREATE TABLE confirmation_attempts (
 id TEXT PRIMARY KEY,
 delivery_id TEXT NOT NULL REFERENCES confirmation_deliveries(id) ON DELETE CASCADE,
 ordinal INTEGER NOT NULL, event TEXT NOT NULL,
 provider TEXT, provider_code TEXT, created_at TEXT NOT NULL,
 UNIQUE(delivery_id,ordinal,event)
);
CREATE TRIGGER erase_response_confirmations BEFORE DELETE ON responses BEGIN
 DELETE FROM rer_mail_development_outbox WHERE json_extract(message,'$.deliveryId')='confirmation:'||OLD.id;
 DELETE FROM confirmation_deliveries WHERE response_id=OLD.id;
END;

CREATE TRIGGER erase_confirmation_capture BEFORE DELETE ON confirmation_deliveries BEGIN
 DELETE FROM rer_mail_development_outbox WHERE json_extract(message,'$.deliveryId')=OLD.id;
END;
CREATE TRIGGER IF NOT EXISTS form_import_epoch_confirmation_deliveries_insert BEFORE INSERT ON confirmation_deliveries BEGIN SELECT RAISE(ABORT,'IMPORT_NATIVE_PUBLICATION_CHANGED') WHERE EXISTS(SELECT 1 FROM form_import_native_publication_fences WHERE target_id IN (SELECT NEW.response_id AS target_id)); UPDATE form_import_native_clock SET revision=revision+1 WHERE id=1 AND EXISTS(SELECT target_id FROM (SELECT NEW.response_id AS target_id) WHERE target_id IN (SELECT target_id FROM form_import_targets)); INSERT INTO form_import_native_epochs(target_id,revision) SELECT target_id,(SELECT revision FROM form_import_native_clock WHERE id=1) FROM (SELECT target_id FROM (SELECT NEW.response_id AS target_id) WHERE target_id IN (SELECT target_id FROM form_import_targets)) WHERE 1 ON CONFLICT(target_id) DO UPDATE SET revision=excluded.revision; END;
CREATE TRIGGER IF NOT EXISTS form_import_epoch_confirmation_deliveries_update BEFORE UPDATE ON confirmation_deliveries BEGIN SELECT RAISE(ABORT,'IMPORT_NATIVE_PUBLICATION_CHANGED') WHERE EXISTS(SELECT 1 FROM form_import_native_publication_fences WHERE target_id IN (SELECT OLD.response_id AS target_id UNION SELECT NEW.response_id AS target_id)); UPDATE form_import_native_clock SET revision=revision+1 WHERE id=1 AND EXISTS(SELECT target_id FROM (SELECT OLD.response_id AS target_id UNION SELECT NEW.response_id AS target_id) WHERE target_id IN (SELECT target_id FROM form_import_targets)); INSERT INTO form_import_native_epochs(target_id,revision) SELECT target_id,(SELECT revision FROM form_import_native_clock WHERE id=1) FROM (SELECT target_id FROM (SELECT OLD.response_id AS target_id UNION SELECT NEW.response_id AS target_id) WHERE target_id IN (SELECT target_id FROM form_import_targets)) WHERE 1 ON CONFLICT(target_id) DO UPDATE SET revision=excluded.revision; END;
